    agentForm:$('agentForm'), loadPresetsButton:$('loadPresetsButton'), fetchParamsButton:$('fetchParamsButton'), presetSelect:$('presetSelect'), paramsRaw:$('paramsRaw'), fetchPoolButton:$('fetchPoolButton'), addProfileButton:$('addProfileButton'), savePoolButton:$('savePoolButton'), poolProfileRows:$('poolProfileRows'),
    policyForm:$('policyForm'), fetchPolicyButton:$('fetchPolicyButton'), policyRaw:$('policyRaw'),
    kanbanSubtitle:$('kanbanSubtitle'), kanbanBoard:$('kanbanBoard'), taskGraph:$('taskGraph'), metricTasks:$('metricTasks'), metricActive:$('metricActive'), metricDone:$('metricDone'), metricAgents:$('metricAgents'), refreshKanbanButton:$('refreshKanbanButton'), liveKanbanButton:$('liveKanbanButton'), taskTitle:$('taskTitle'), taskDetail:$('taskDetail'), refreshTaskDetailButton:$('refreshTaskDetailButton'), taskReassessParentButton:$('taskReassessParentButton'), taskMessageForm:$('taskMessageForm'), taskMessageInput:$('taskMessageInput'),
    infraSubtitle:$('infraSubtitle'), infraMetricTasks:$('infraMetricTasks'), infraMetricWorkers:$('infraMetricWorkers'), infraMetricKbs:$('infraMetricKbs'), infraMetricTbs:$('infraMetricTbs'), infraMetricTools:$('infraMetricTools'), infraMetricUniverses:$('infraMetricUniverses'), infraMetricVstores:$('infraMetricVstores'), infraMetricArtifacts:$('infraMetricArtifacts'), infraMetricWarnings:$('infraMetricWarnings'), infraMetricAuditEvents:$('infraMetricAuditEvents'), refreshInfrastructureButton:$('refreshInfrastructureButton'), infraOverview:$('infraOverview'), infraWarnings:$('infraWarnings'), infraAuditSummary:$('infraAuditSummary'), infraWorkerSessions:$('infraWorkerSessions'), infraTaskInfras:$('infraTaskInfras'), infraResourceInventory:$('infraResourceInventory'), infraLocalityEdges:$('infraLocalityEdges'), infraRaw:$('infraRaw'),
