  async function savePolicy(){ const r=await api(`/sessions/${encodeURIComponent(state.sessionId)}/params?${tokenQuery()}`,{method:'PATCH',body:JSON.stringify(policyFromForm())}); toast('Policy saved'); log(r); await fetchPolicy(); }
  async function loadPresets(){ const data=await api(`/agent-config-presets?${tokenQuery()}`); state.presets=Array.isArray(data)?data:(data.presets||[]); el.presetSelect.innerHTML='<option value="">Choose preset…</option>'+state.presets.map((p,i)=>`<option value="${i}">${esc(p.name||p.model||'preset '+(i+1))}</option>`).join(''); toast(`Loaded ${state.presets.length} presets`); }
