  function infraCount(path, fallback=0){ try{ return path()==null ? fallback : Number(path())||fallback; }catch{return fallback;} }
  function setText(node, value){ if(node) node.textContent=String(value ?? ''); }
  function infraResourceItems(snapshot){ const r=snapshot?.resources||{}; return [...(r.kbs||[]),...(r.tbs||[]),...(r.tools||[]),...(r.universes||[]),...(r.vstores||[]),...(r.artifacts||[])]; }
  function infraBadge(text, tone='info'){ return `<span class="infra-badge tone-${esc(tone)}">${esc(text)}</span>`; }
  function renderInfraOverview(snapshot){ if(!el.infraOverview) return; if(!snapshot){ el.infraOverview.classList.add('empty'); el.infraOverview.textContent='Load a snapshot to inspect runtime infrastructure.'; return; } el.infraOverview.classList.remove('empty'); const gw=snapshot.gateway_runtime||{}; const main=snapshot.main_infrastructure||{}; const orch=snapshot.orchestration||{}; const ctx=main.context||{}; const chat=main.chat||{}; const mem=main.memory||{}; el.infraOverview.innerHTML=`<div class="infra-card-grid"><article><span>Gateway runtime</span><strong>${esc(gw.workflow_class||'unknown')}</strong><small>${gw.db_client_present?'shared db_client present':'no shared db_client'} · ${esc(gw.run_control_status||'idle')}</small></article><article><span>Main infrastructure</span><strong>${esc(main.class||'unknown')}</strong><small>chat ${esc(chat.entries||0)} · ctx ${esc(ctx.entries||0)} / ${esc(ctx.tokens||0)} tokens</small></article><article><span>Orchestration</span><strong>${orch.enabled?'enabled':'disabled'}</strong><small>${esc(orch.adapter||'no adapter')} · ${esc(orch.task_count||0)} tasks</small></article><article><span>Memory</span><strong>${esc(mem.class||'unknown')}</strong><small>${esc((mem.vstores||[]).length)} vstores · fragments ${esc(mem.fragments||0)}</small></article></div>`; }
  function infraMetaLine(r){ const m=r?.metadata||{}; const bits=[]; ['collection_name','text_collection_name','vision_collection_name','table_collection_name','persist_directory','path','kind','tool_count','tool_names','language','version','status','toolbox','vstore','index_vstore','doc_vstore'].forEach(k=>{ if(m[k]!=null) bits.push(`${k}: ${m[k]}`); }); return bits.join(' · '); }
  function infraWarningTone(w={}){ const s=String(w.severity||'info').toLowerCase(); return s==='error'?'error':(s==='warning'?'warning':'info'); }
  function renderInfraWarnings(snapshot){ if(!el.infraWarnings) return; const rows=snapshot?.warnings||[]; if(!rows.length){ el.infraWarnings.classList.add('empty'); el.infraWarnings.textContent='No infrastructure warnings.'; return; } el.infraWarnings.classList.remove('empty'); el.infraWarnings.innerHTML=rows.map(w=>`<article class="infra-warning tone-${esc(infraWarningTone(w))}"><div>${infraBadge(w.severity||'info',infraWarningTone(w))}<strong>${esc(w.code||'warning')}</strong><small>${esc(w.owner||'')}</small></div><p>${esc(w.message||'')}</p>${w.collection_name?`<code>${esc(w.collection_name)}</code>`:''}</article>`).join(''); }
  function renderInfraAuditSummary(snapshot){ if(!el.infraAuditSummary) return; const a=snapshot?.audit_summary||{}; if(!a.total_events){ el.infraAuditSummary.classList.add('empty'); el.infraAuditSummary.textContent='No task infrastructure events.'; return; } el.infraAuditSummary.classList.remove('empty'); const counts=Object.entries(a.counts_by_type||{}).map(([k,v])=>`<span>${esc(k)} <strong>${esc(v)}</strong></span>`).join('') || '<span>No typed events</span>'; const sev=a.severity_counts||{}; const recent=(a.recent_events||[]).map(ev=>`<article class="infra-audit-event tone-${esc(ev.severity||'info')}"><div>${infraBadge(ev.severity||'info',ev.severity||'info')}<strong>${esc(ev.type||'event')}</strong><small>${esc(ev.task_id||'')}</small></div><p>${esc(ev.message||ev.status||ev.action||'')}</p></article>`).join(''); el.infraAuditSummary.innerHTML=`<div class="infra-audit-grid"><article><span>Total events</span><strong>${esc(a.total_events||0)}</strong></article><article><span>Tasks with events</span><strong>${esc(a.tasks_with_events||0)}</strong></article><article><span>Errors</span><strong>${esc(sev.error||0)}</strong></article><article><span>Warnings</span><strong>${esc(sev.warning||0)}</strong></article></div><div class="infra-audit-counts">${counts}</div>${recent?`<div class="infra-audit-events">${recent}</div>`:''}`; }
  function renderWorkerSessions(snapshot){ if(!el.infraWorkerSessions) return; const rows=snapshot?.worker_sessions||[]; if(!rows.length){ el.infraWorkerSessions.classList.add('empty'); el.infraWorkerSessions.textContent='No worker sessions.'; return; } el.infraWorkerSessions.classList.remove('empty'); el.infraWorkerSessions.innerHTML=`<table><thead><tr><th>Task</th><th>Agent</th><th>Workflow</th><th>db_client</th><th>Chat</th><th>Context</th><th>Memory collections</th><th>Resources</th></tr></thead><tbody>${rows.map(w=>{ const cols=Object.entries(w.memory_collections||{}).map(([k,v])=>`${k}: ${v||'unknown'}`).join(' · ') || ((w.infrastructure?.memory?.vstores||[]).map(v=>v.collection_name||v.name).filter(Boolean).join(' · ')||'none'); return `<tr><td><code>${esc(w.task_id||'')}</code></td><td>${esc(w.agent_name||'')}</td><td>${esc(w.workflow_class||'')}</td><td>${infraBadge(w.db_client_inherited?'inherited':'missing',w.db_client_inherited?'info':'warning')}</td><td>${esc(w.chat_entries||0)}</td><td>${esc(w.context_entries||0)} / ${esc(w.context_tokens||0)}</td><td>${esc(cols)}</td><td>KB ${esc(w.resource_counts?.kbs||0)} · TB ${esc(w.resource_counts?.tbs||0)} · Tools ${esc(w.resource_counts?.tools||0)} · UN ${esc(w.resource_counts?.universes||0)} · VS ${esc(w.resource_counts?.vstores||0)}</td></tr>`; }).join('')}</tbody></table>`; }
  function renderTaskInfras(snapshot){ if(!el.infraTaskInfras) return; const rows=snapshot?.task_infrastructures||[]; if(!rows.length){ el.infraTaskInfras.classList.add('empty'); el.infraTaskInfras.textContent='No task infrastructure rows.'; return; } el.infraTaskInfras.classList.remove('empty'); el.infraTaskInfras.innerHTML=`<table><thead><tr><th>Task</th><th>Workflow</th><th>Events</th><th>Event types</th><th>Local state</th><th>Artifacts</th><th>Session dir</th><th>Artifact dir</th></tr></thead><tbody>${rows.map(r=>`<tr><td><code>${esc(r.task_id||'')}</code></td><td>${esc(r.workflow_type||r.class||'')}</td><td>${esc(r.events||0)}</td><td>${esc(Object.entries(r.event_summary?.counts_by_type||{}).map(([k,v])=>`${k}:${v}`).join(' · ')||'none')}</td><td>msg ${esc(r.local_message_count||0)} · facts ${esc(r.local_fact_count||0)} · child ${esc(r.child_summary_count||0)} · deps ${esc(r.dependency_summary_count||0)} · hist ${esc(r.compressed_history_count||0)} · tools ${esc(r.resource_counts?.tools||0)}</td><td>${esc(r.artifact_count||0)}</td><td>${esc(r.session_dir||'')}</td><td>${esc(r.artifact_dir||'')}</td></tr>`).join('')}</tbody></table>`; }
  function renderResourceInventory(snapshot){ if(!el.infraResourceInventory) return; const items=infraResourceItems(snapshot); if(!items.length){ el.infraResourceInventory.classList.add('empty'); el.infraResourceInventory.textContent='No resources discovered.'; return; } el.infraResourceInventory.classList.remove('empty'); el.infraResourceInventory.innerHTML=items.map(r=>`<article class="infra-resource-card kind-${esc(r.kind||'resource')}"><div class="row between"><strong>${esc(r.name||r.id||'resource')}</strong>${infraBadge(r.kind||'resource',r.destructive_capable?'warning':'info')}</div><small>${esc(r.locality||'unknown')} · ${esc(r.owner_type||'owner')}:${esc(r.owner_id||'')}</small><p>${esc(r.source||'unknown source')} · ${r.shared?'shared':'isolated'} · ${r.destructive_capable?'destructive-capable':'safe-read'}</p>${infraMetaLine(r)?`<code>${esc(infraMetaLine(r))}</code>`:''}</article>`).join(''); }
  function renderLocalityEdges(snapshot){ if(!el.infraLocalityEdges) return; const edges=snapshot?.locality_edges||[]; if(!edges.length){ el.infraLocalityEdges.classList.add('empty'); el.infraLocalityEdges.textContent='No locality edges.'; return; } el.infraLocalityEdges.classList.remove('empty'); el.infraLocalityEdges.innerHTML=edges.map(e=>`<div class="infra-edge"><code>${esc(e.from||'')}</code><span>${esc(e.kind||'uses')}</span><code>${esc(e.to||'')}</code><small>${esc(e.label||'')}</small></div>`).join(''); }
  function renderInfrastructureSnapshot(){ const snap=state.infraSnapshot; setText(el.infraSubtitle, snap ? `${snap.type||'infrastructure_snapshot'} · ${snap.timestamp||''}` : 'No infrastructure snapshot loaded.'); setText(el.infraMetricTasks, infraCount(()=>snap.orchestration.task_count, (snap?.tasks||[]).length)); setText(el.infraMetricWorkers, (snap?.worker_sessions||[]).length); setText(el.infraMetricKbs, snap?.resource_counts?.kbs||0); setText(el.infraMetricTbs, snap?.resource_counts?.tbs||0); setText(el.infraMetricTools, snap?.resource_counts?.tools||0); setText(el.infraMetricUniverses, snap?.resource_counts?.universes||0); setText(el.infraMetricVstores, snap?.resource_counts?.vstores||0); setText(el.infraMetricArtifacts, snap?.resource_counts?.artifacts||0); setText(el.infraMetricWarnings, (snap?.warnings||[]).length); setText(el.infraMetricAuditEvents, snap?.audit_summary?.total_events||0); renderInfraOverview(snap); renderInfraWarnings(snap); renderInfraAuditSummary(snap); renderWorkerSessions(snap); renderTaskInfras(snap); renderResourceInventory(snap); renderLocalityEdges(snap); if(el.infraRaw) el.infraRaw.textContent=snap?JSON.stringify(snap,null,2):''; }
  async function fetchInfrastructureSnapshot(){ if(!state.sessionId) throw new Error('Connect a session first.'); state.infraSnapshot=await api(`/sessions/${encodeURIComponent(state.sessionId)}/infrastructure/snapshot?${tokenQuery()}`); renderInfrastructureSnapshot(); toast('Infrastructure snapshot loaded'); return state.infraSnapshot; }

  function collabSnapshot(){ return state.collaborationSnapshot || {participants:[], invites:[], join_requests:[], a2a_peers:[], a2a_task_requests:[], audit_recent:[], audit_summary:{}}; }
  function collabCssEscape(value){ if(window.CSS && CSS.escape) return CSS.escape(String(value||'')); return String(value||'').replace(/[^A-Za-z0-9_-]/g, '\\$&'); }
  function collabRoleSelect(id, current='human'){ const roles=['human','observer','assistant_agent','tool_agent','controller','gui_client','tui_client']; return `<select data-join-role="${esc(id)}">${roles.map(r=>`<option value="${esc(r)}" ${r===current?'selected':''}>${esc(r)}</option>`).join('')}</select>`; }
  function renderCollaborationSnapshot(){ const snap=collabSnapshot(); const participants=snap.participants||[]; const invites=snap.invites||[]; const joins=snap.join_requests||[]; const a2a=snap.a2a_peers||[]; const a2aTasks=snap.a2a_task_requests||[]; const audit=snap.audit_recent||[]; const pending=joins.filter(j=>String(j.status||'').toLowerCase()==='pending'); setText(el.collabSubtitle, state.collaborationSnapshot ? `collaboration_snapshot · ${snap.timestamp||''}` : 'No collaboration snapshot loaded.'); setText(el.collabMetricParticipants, participants.length); setText(el.collabMetricActive, participants.filter(p=>p.active!==false).length); setText(el.collabMetricInvites, invites.length); setText(el.collabMetricPending, pending.length); setText(el.collabMetricA2A, a2a.length); setText(el.collabMetricAudit, snap.audit_summary?.total_events ?? audit.length); renderParticipants(participants); renderInvites(invites); renderJoinRequests(joins); renderA2APeers(a2a); renderA2ATaskRequests(a2aTasks); renderCollabAudit(audit, snap.audit_summary||{}); if(el.collabRaw) el.collabRaw.textContent=state.collaborationSnapshot?JSON.stringify(state.collaborationSnapshot,null,2):''; }
  function renderParticipants(rows=[]){ if(!el.collabParticipants) return; if(!rows.length){ el.collabParticipants.classList.add('empty'); el.collabParticipants.textContent='No participants loaded.'; return; } el.collabParticipants.classList.remove('empty'); el.collabParticipants.innerHTML=`<table><thead><tr><th>Participant</th><th>Role</th><th>Client</th><th>Auth</th><th>Status</th><th>Permissions</th></tr></thead><tbody>${rows.map(p=>{ const perms=Object.entries(p.permissions||{}).filter(([,v])=>v).map(([k])=>k.replace(/^can_/,'')); return `<tr><td><code>${esc(p.participant_id||p.id||'')}</code></td><td>${esc(p.role||p.participant_role||'')}</td><td>${esc(p.client_type||'')}</td><td>${esc(p.auth_mode||'account_token')}</td><td>${infraBadge(p.active===false?'inactive':'active',p.active===false?'warning':'info')}</td><td>${esc(perms.slice(0,6).join(', ')||'none')}${perms.length>6?' …':''}</td></tr>`; }).join('')}</tbody></table>`; }
  function renderA2APeers(rows=[]){ if(el.a2aTaskPeer){ const current=el.a2aTaskPeer.value; el.a2aTaskPeer.innerHTML='<option value="">Select an A2A peer</option>'+rows.map(p=>`<option value="${esc(p.peer_id||'')}">${esc(p.display_name||p.agent_id||p.peer_id||'peer')} · ${esc(p.peer_id||'')}</option>`).join(''); if(current) el.a2aTaskPeer.value=current; } if(!el.collabA2APeers) return; if(!rows.length){ el.collabA2APeers.classList.add('empty'); el.collabA2APeers.textContent='No A2A peers loaded.'; return; } el.collabA2APeers.classList.remove('empty'); el.collabA2APeers.innerHTML=`<table><thead><tr><th>Peer</th><th>Participant</th><th>Agent</th><th>Status</th><th>Auth</th><th>Capabilities</th><th>Last seen</th></tr></thead><tbody>${rows.map(p=>`<tr><td><code>${esc(p.peer_id||'')}</code></td><td><code>${esc(p.participant_id||'')}</code></td><td><strong>${esc(p.display_name||p.agent_id||'')}</strong><br><small>${esc(p.protocol||'a2a')} ${esc(p.protocol_version||'')}</small></td><td>${infraBadge(p.status||'unknown',p.status==='active'?'info':'warning')}</td><td>${esc(p.auth_mode||'')}</td><td>${esc((p.capabilities||[]).slice(0,8).join(', ')||'none')}${(p.capabilities||[]).length>8?' …':''}</td><td>${esc(p.last_seen_at||p.connected_at||'')}</td></tr>`).join('')}</tbody></table>`; }
  function renderA2ATaskRequests(rows=[]){ if(!el.collabA2ATasks) return; if(!rows.length){ el.collabA2ATasks.classList.add('empty'); el.collabA2ATasks.textContent='No A2A task requests loaded.'; return; } el.collabA2ATasks.classList.remove('empty'); el.collabA2ATasks.innerHTML=`<table><thead><tr><th>Request</th><th>Peer</th><th>Task</th><th>Status</th><th>Content</th><th>Created</th></tr></thead><tbody>${rows.map(r=>`<tr><td><code>${esc(r.request_id||'')}</code></td><td><code>${esc(r.peer_id||'')}</code></td><td>${esc(r.task_id||'')}</td><td>${infraBadge(r.status||'queued',r.status==='queued'?'warning':'info')}</td><td>${esc(String(r.content||'').slice(0,180))}</td><td>${esc(r.created_at||'')}</td></tr>`).join('')}</tbody></table>`; }
  function collabAuditTone(ev={}){ const sev=String(ev.severity||'info').toLowerCase(); if(sev==='error') return 'error'; if(sev==='warning') return 'warning'; return 'info'; }
  function renderCollabAudit(rows=[], summary={}){ if(!el.collabAudit) return; if(!rows.length){ el.collabAudit.classList.add('empty'); el.collabAudit.textContent='No collaboration audit events loaded.'; return; } el.collabAudit.classList.remove('empty'); const counts=Object.entries(summary.counts_by_type||{}).slice(0,10).map(([k,v])=>`<span>${esc(k)} <strong>${esc(v)}</strong></span>`).join(''); const events=rows.map(ev=>{ const tone=collabAuditTone(ev); const meta=ev.metadata&&Object.keys(ev.metadata).length?`<details><summary>Metadata</summary><pre>${esc(JSON.stringify(ev.metadata,null,2))}</pre></details>`:''; return `<article class="collab-audit-event tone-${esc(tone)}"><div class="collab-audit-head">${infraBadge(ev.severity||'info',tone)}<strong>${esc(ev.type||'event')}</strong><time>${esc(String(ev.timestamp||'').slice(0,19))}</time></div><p>${esc(ev.message||'')}</p><small>${ev.actor_participant_id?`participant ${esc(ev.actor_participant_id)}`:''}${ev.actor_peer_id?` · peer ${esc(ev.actor_peer_id)}`:''}</small>${meta}</article>`; }).join(''); el.collabAudit.innerHTML=`${counts?`<div class="collab-audit-counts">${counts}</div>`:''}<div class="collab-audit-events">${events}</div>`; }
  function renderInvites(rows=[]){ if(!el.collabInvites) return; if(!rows.length){ el.collabInvites.classList.add('empty'); el.collabInvites.textContent='No invites loaded.'; return; } el.collabInvites.classList.remove('empty'); el.collabInvites.innerHTML=`<table><thead><tr><th>Invite</th><th>Role</th><th>Status</th><th>Uses</th><th>Expires</th><th>Token</th><th>Action</th></tr></thead><tbody>${rows.map(i=>`<tr><td><code>${esc(i.invite_id||'')}</code></td><td>${esc(i.role||'')}</td><td>${infraBadge(i.status||'unknown',i.status==='active'?'info':'warning')}</td><td>${esc(i.used_count||0)} / ${esc(i.max_uses||1)}</td><td>${esc(i.expires_at||'never')}</td><td><code>${esc(i.token_preview||i.invite_token||'***REDACTED***')}</code></td><td><button class="ghost danger" type="button" data-revoke-invite="${esc(i.invite_id||'')}">Revoke</button></td></tr>`).join('')}</tbody></table>`; el.collabInvites.querySelectorAll('[data-revoke-invite]').forEach(b=>b.onclick=()=>revokeInvite(b.dataset.revokeInvite).catch(e=>toast(e.message))); }
  function renderJoinRequests(rows=[]){ if(!el.collabJoinRequests) return; if(!rows.length){ el.collabJoinRequests.classList.add('empty'); el.collabJoinRequests.textContent='No join requests loaded.'; return; } el.collabJoinRequests.classList.remove('empty'); el.collabJoinRequests.innerHTML=`<table><thead><tr><th>Request</th><th>Participant</th><th>Client</th><th>Role</th><th>Status</th><th>Reason</th><th>Actions</th></tr></thead><tbody>${rows.map(j=>{ const pending=String(j.status||'')==='pending'; return `<tr><td><code>${esc(j.request_id||'')}</code></td><td>${esc(j.requested_participant_id||'')}</td><td>${esc(j.client_type||'')}</td><td>${pending?collabRoleSelect(j.request_id,j.requested_role||'human'):esc(j.approved_role||j.requested_role||'')}</td><td>${infraBadge(j.status||'unknown',pending?'warning':(j.status==='approved'?'info':'error'))}</td><td>${esc(j.reason||'')}</td><td>${pending?`<button class="primary" type="button" data-approve-join="${esc(j.request_id||'')}">Accept</button><button class="ghost danger" type="button" data-reject-join="${esc(j.request_id||'')}">Reject</button>`:''}</td></tr>`; }).join('')}</tbody></table>`; el.collabJoinRequests.querySelectorAll('[data-approve-join]').forEach(b=>b.onclick=()=>approveJoinRequest(b.dataset.approveJoin).catch(e=>toast(e.message))); el.collabJoinRequests.querySelectorAll('[data-reject-join]').forEach(b=>b.onclick=()=>rejectJoinRequest(b.dataset.rejectJoin).catch(e=>toast(e.message))); }
  async function fetchParticipants(){ const data=await api(`/sessions/${encodeURIComponent(state.sessionId)}/participants?${tokenQuery()}`); state.collaborationSnapshot=Object.assign({}, collabSnapshot(), {type:'collaboration_snapshot', session_id:state.sessionId, timestamp:new Date().toISOString(), participants:data.participants||[]}); renderCollaborationSnapshot(); return data; }
