  async function fetchJoinRequests(){ const data=await api(`/sessions/${encodeURIComponent(state.sessionId)}/join-requests?${tokenQuery()}`); state.collaborationSnapshot=Object.assign({}, collabSnapshot(), {type:'collaboration_snapshot', session_id:state.sessionId, timestamp:new Date().toISOString(), join_requests:data.join_requests||[]}); renderCollaborationSnapshot(); return data; }
  async function fetchCollaborationSnapshot(){ if(!state.sessionId) throw new Error('Connect a session first.'); try{ state.collaborationSnapshot=await api(`/sessions/${encodeURIComponent(state.sessionId)}/collaboration/snapshot?${tokenQuery()}`); renderCollaborationSnapshot(); }catch(e){ await Promise.all([fetchParticipants(), fetchInvites(), fetchJoinRequests()]); } toast('Collaboration snapshot loaded'); return state.collaborationSnapshot; }
  function inviteBodyFromForm(){ return {role:el.inviteRole?.value||'human', expires_in_seconds:Number(el.inviteTtl?.value||3600), max_uses:Number(el.inviteMaxUses?.value||1), participant_id_hint:el.inviteParticipantHint?.value||null}; }
