  async function sendA2ATaskRequest(){ const peerId=(el.a2aTaskPeer?.value||'').trim(); const content=(el.a2aTaskContent?.value||'').trim(); if(!peerId) throw new Error('Select an A2A peer.'); if(!content) throw new Error('Enter a passive A2A task request.'); const body={content,task_id:(el.a2aTaskId?.value||'').trim()||null,metadata:{source:'gateway_web'}}; const out=await api(`/sessions/${encodeURIComponent(state.sessionId)}/a2a/peers/${encodeURIComponent(peerId)}/task-requests?${tokenQuery()}`,{method:'POST',body:JSON.stringify(body)}); toast('A2A task request queued'); if(el.a2aTaskContent) el.a2aTaskContent.value=''; if(el.a2aTaskId) el.a2aTaskId.value=''; log({type:'collaboration_a2a_task_request_queued', peer_id:peerId, request_id:out.task_request?.request_id}); await fetchCollaborationSnapshot().catch(()=>{}); return out; }
