  function renderTaskBadges(task, detail){ const badges=taskBadges(task, detail); if(!badges.length) return ''; return `<span class="task-badges">${badges.map(([cls,label])=>`<span class="task-badge ${esc(cls)}">${esc(label)}</span>`).join('')}</span>`; }
  function taskActionAllowed(action, status){ const s=String(status||'unknown').toLowerCase(); const terminal=['completed','done','succeeded','success','failed','cancelled','canceled'].includes(s); if(action==='pause') return ['queued','ready','pending','created','running','active','in_progress'].includes(s); if(action==='resume') return ['waiting','paused','blocked','needs_user'].includes(s); if(action==='retry') return terminal || ['failed','cancelled','canceled'].includes(s); if(action==='cancel') return !terminal && s!=='unknown'; if(action==='cancel_subtree') return !!s && s!=='unknown' && !['completed','done','succeeded','success'].includes(s); if(action==='retry_subtree') return !!s && s!=='unknown'; if(action==='replan') return !!s && s!=='unknown' && !['cancelled','canceled'].includes(s); return true; }
  function updateTaskActionStates(){ const bundle=selectedTaskBundle(); const task=bundle.task; const status=taskStatusValue(task); $$('.task-action').forEach(b=>{ const allowed=!!task && taskActionAllowed(b.dataset.taskAction, status); b.disabled=!allowed; b.classList.toggle('task-action-invalid', !allowed); b.title=allowed ? '' : (task ? `Action ${b.dataset.taskAction} is not valid while task is ${status}.` : 'Select a task first.'); }); if(el.taskReassessParentButton){ const hasParent=!!parentTaskId(task); el.taskReassessParentButton.disabled=!hasParent; el.taskReassessParentButton.title=hasParent?'':'Select a child task with a parent to request reassessment.'; } }
  function renderKanban(){ const list=tasks(); const groups=[['queued','Queued'],['running','Running'],['waiting','Waiting'],['completed','Done'],['failed','Failed']]; el.metricTasks.textContent=list.length; el.metricActive.textContent=list.filter(t=>['running','active','in_progress'].includes(tstatus(t))).length; el.metricDone.textContent=list.filter(t=>groupStatus(tstatus(t))==='completed').length; el.metricAgents.textContent=(state.snapshot?.agent_pool_summary?.total_agents ?? (state.snapshot?.agent_pool||state.snapshot?.agents||[]).length)||0; el.kanbanSubtitle.textContent=state.snapshot ? `${state.snapshot.enabled?'Enabled':'Disabled'} · ${state.snapshot.started?'runtime started':'runtime stopped'} · ${state.snapshot.timestamp||''}` : 'No snapshot loaded.'; el.kanbanBoard.innerHTML=groups.map(([id,title])=>{ const xs=list.filter(t=>groupStatus(tstatus(t))===id); const cards=xs.map(t=>{ const id=tid(t); const detail=(state.taskDetails||{})[id]; return `<button class="kanban-card ${esc(tstatus(t))}${id===state.selectedTaskId?' is-selected':''}" data-task-id="${esc(id)}"><span class="card-title"><strong>${esc(tname(t))}</strong><em>${esc(id).slice(0,8)}</em></span><span>${esc(tobj(t)).slice(0,220)||'No objective'}</span><span class="pill">${esc(tstatus(t))}</span>${renderTaskBadges(t, detail)}</button>`; }).join('')||'<div class="empty">No tasks</div>'; return `<section class="kanban-column"><header><span>${title}</span><strong>${xs.length}</strong></header><div class="kanban-cards">${cards}</div></section>`; }).join(''); $$('.kanban-card').forEach(c=>c.onclick=()=>openTaskDetail(c.dataset.taskId)); renderTaskGraph(); renderTaskDetail(); updateTaskActionStates(); }
  function fallbackGraphPayload(){ const list=tasks(); const edges=[]; list.forEach(t=>{ const id=tid(t); const spec=t.spec||{}; if(!id) return; if(spec.parent_id||t.parent_id) edges.push({from:spec.parent_id||t.parent_id,to:id,kind:'parent_child'}); (spec.dependencies||t.dependencies||[]).forEach(dep=>edges.push({from:dep,to:id,kind:'dependency'})); (t.waiting_on||[]).forEach(child=>edges.push({from:id,to:child,kind:'waiting_on'})); }); return {nodes:list.map(t=>({id:tid(t),name:tname(t),status:tstatus(t),parent_id:t.spec?.parent_id||t.parent_id,depth:t.depth||0,waiting_on:t.waiting_on||[]})).filter(n=>n.id),edges,roots:list.filter(t=>!(t.spec?.parent_id||t.parent_id)).map(t=>tid(t)).filter(Boolean)}; }
  function domGraphPayload(){ const cards=$$('.kanban-card[data-task-id]'); const nodes=cards.map(card=>{ const id=String(card.dataset.taskId||''); const status=String(card.querySelector('.pill')?.textContent||'unknown').trim().toLowerCase(); const name=String(card.querySelector('.card-title strong')?.textContent||id||'task').trim(); return id?{id,name,status,depth:0,dom_fallback:true}:null; }).filter(Boolean); return {nodes,edges:[],roots:nodes.map(n=>n.id),dom_fallback:true}; }
  function graphPayload(){ const fallback=fallbackGraphPayload(); const raw=state.snapshot?.task_graph; const rawNodes=Array.isArray(raw?.nodes)?raw.nodes:[]; let base; if(!rawNodes.length) base=fallback; else { const nodes=rawNodes.map(n=>Object.assign({},n,{id:String(n.id||n.task_id||n.node_id||'')})).filter(n=>n.id); const ids=new Set(nodes.map(n=>n.id)); fallback.nodes.forEach(n=>{ if(!ids.has(n.id)){ nodes.push(n); ids.add(n.id); } }); const edges=[]; const edgeKeys=new Set(); function addEdge(e){ const from=String(e?.from||e?.source||e?.parent_id||''); const to=String(e?.to||e?.target||e?.child_id||''); if(!from||!to) return; const kind=String(e?.kind||e?.type||'edge'); const key=`${from}->${to}:${kind}`; if(edgeKeys.has(key)) return; edgeKeys.add(key); edges.push({from,to,kind}); } (Array.isArray(raw?.edges)?raw.edges:[]).forEach(addEdge); fallback.edges.forEach(addEdge); base={nodes,edges,roots:Array.isArray(raw?.roots)?raw.roots:fallback.roots}; } if(!Array.isArray(base.nodes)||!base.nodes.length){ const dom=domGraphPayload(); if(dom.nodes.length) return dom; } return base; }
  function graphDiagnostic(){ const raw=state.snapshot?.task_graph||{}; const rawNodeCount=Array.isArray(raw.nodes)?raw.nodes.length:0; const rawEdgeCount=Array.isArray(raw.edges)?raw.edges.length:0; return `Snapshot tasks: ${tasks().length}; task_graph nodes: ${rawNodeCount}; task_graph edges: ${rawEdgeCount}; DOM cards: ${$$('.kanban-card[data-task-id]').length}; selected: ${state.selectedTaskId||'none'}.`; }
  function renderTaskGraph(){ if(!el.taskGraph) return; const graph=graphPayload(); const nodes=Array.isArray(graph.nodes)?graph.nodes:[]; const edges=Array.isArray(graph.edges)?graph.edges:[]; if(!nodes.length){ el.taskGraph.classList.add('empty'); el.taskGraph.innerHTML=`<div>No graph loaded.</div><small class="graph-diagnostic">${esc(graphDiagnostic())}</small>`; return; } el.taskGraph.classList.remove('empty'); const selected=state.selectedTaskId; const related=new Set(); if(selected){ edges.forEach(e=>{ if(e.from===selected) related.add(e.to); if(e.to===selected) related.add(e.from); }); } const edgeKey=e=>`${String(e.from||'').slice(0,8)} → ${String(e.to||'').slice(0,8)}`; const ordered=selected?[...nodes.filter(n=>n.id===selected),...nodes.filter(n=>n.id!==selected)]:nodes; const nodeHtml=ordered.map(n=>{ const id=String(n.id||n.task_id||n.node_id||''); const detail=(state.taskDetails||{})[id]; const task=snapshotTaskById(id)||n; const depth=Number(n.depth||task.depth||0); const children=edges.filter(e=>e.from===id&&e.kind!=='dependency').length; const deps=edges.filter(e=>e.to===id&&e.kind==='dependency').length; const cls=`graph-node ${esc(String(n.status||tstatus(task)))}${id===selected?' is-selected':''}${related.has(id)?' is-related':''}${n.dom_fallback?' dom-fallback':''}`; return `<button type="button" class="${cls}" style="--depth:${Math.min(8,Math.max(0,depth))}" data-open-task-detail="${esc(id)}"><span><strong>${esc(n.name||tname(task))}</strong><em>${esc(id.slice(0,8))}</em></span><span class="pill">${esc(String(n.status||tstatus(task)))}</span>${renderTaskBadges(task,detail)}<small>${children} children · ${deps} deps${n.dom_fallback?' · card fallback':''}</small></button>`; }).join(''); const diag=graph.dom_fallback?`<p class="graph-diagnostic">Graph built from visible Kanban cards because snapshot graph data was empty. ${esc(graphDiagnostic())}</p>`:''; const edgeHtml=edges.length?`<div class="graph-edges"><h3>Edges</h3>${edges.slice(0,80).map(e=>`<div class="graph-edge ${esc(e.kind||'edge')}${selected&&(e.from===selected||e.to===selected)?' is-related':''}"><span>${esc(edgeKey(e))}</span><em>${esc(e.kind||'edge')}</em></div>`).join('')}${edges.length>80?`<p class="muted">${edges.length-80} more edges hidden.</p>`:''}</div>`:'<div class="empty">No edges</div>'; el.taskGraph.innerHTML=`${diag}<div class="graph-nodes">${nodeHtml}</div>${edgeHtml}`; el.taskGraph.querySelectorAll('[data-open-task-detail]').forEach(b=>b.onclick=()=>openTaskDetail(b.dataset.openTaskDetail)); }
  function renderMapSection(title, value){ const entries=value&&typeof value==='object'?Object.entries(value):[]; if(!entries.length) return ''; return `<section class="detail-section"><h3>${esc(title)}</h3><div class="summary-list">${entries.map(([k,v])=>{ const key=String(k); const body=typeof v==='string'?v:JSON.stringify(v,null,2); return `<article><div class="summary-row-head"><strong>${esc(key.slice(0,18))}</strong><button class="detail-task-link" type="button" data-open-task-detail="${esc(key)}">Open task</button></div><p>${esc(body)}</p></article>`; }).join('')}</div></section>`; }
  function renderListSection(title, value, limit=6){ const items=Array.isArray(value)?value.slice(-limit):[]; if(!items.length) return ''; return `<section class="detail-section"><h3>${esc(title)}</h3><div class="summary-list">${items.map((v,i)=>`<article><strong>${esc(String(v?.role||v?.kind||v?.type||`item ${i+1}`))}</strong><p>${esc(typeof v==='string'?v:JSON.stringify(v,null,2))}</p></article>`).join('')}</div></section>`; }
  async function fetchTaskDetail(taskId=state.selectedTaskId){ if(!taskId) return null; state.taskDetailErrors=state.taskDetailErrors||{}; try{ const detail=await api(`/sessions/${encodeURIComponent(state.sessionId)}/orchestration/tasks/${encodeURIComponent(taskId)}?${tokenQuery()}`); state.taskDetails=state.taskDetails||{}; state.taskDetails[taskId]=detail; state.selectedTaskDetail=detail; delete state.taskDetailErrors[taskId]; renderTaskGraph(); renderTaskDetail(); return detail; }catch(e){ state.taskDetailErrors[taskId]=e.message||String(e); renderTaskDetail(); throw e; } }
